   "codice": "extends RefCounted


func run() -> String:
	var config := ConfigFile.new()
	var text := "[plugin]\nname=\"Awesome Plugin\"\nversion=\"1.2.0\""
	config.parse(text)
	return config.get_value("plugin", "version", "0.0.0")
",
